import heapq
from collections import defaultdict

class HuffmanCoding:
    def __init__(self, text):
        self.text = text
        self.freq = defaultdict(int)
        self.huff = {}

    def calc_freq(self):
        for char in self.text:
            self.freq[char] += 1

    def make_huffman_tree(self):
        heap = [[weight, [char, ""]] for char, weight in self.freq.items()]
        heapq.heapify(heap)
        while len(heap) > 1:
            lo = heapq.heappop(heap)
            hi = heapq.heappop(heap)
            for pair in lo[1:]:
                pair[1] = '0' + pair[1]
            for pair in hi[1:]:
                pair[1] = '1' + pair[1]
            heapq.heappush(heap, [lo[0] + hi[0]] + lo[1:] + hi[1:])
        return sorted(heapq.heappop(heap)[1:], key=lambda p: (len(p[-1]), p))

    def generate_codes(self):
        huff_tree = self.make_huffman_tree()
        for char, code in huff_tree:
            self.huff[char] = code

    def encode(self):
        encoded_text = ''.join([self.huff[char] for char in self.text])
        return encoded_text

    def decode(self, encoded_text):
        decoded_text = ''
        current_code = ''
        for bit in encoded_text:
            current_code += bit
            for char, code in self.huff.items():
                if current_code == code:
                    decoded_text += char
                    current_code = ''
        return decoded_text

# Example usage
text = "this is an example for huffman encoding"
h = HuffmanCoding(text)
h.calc_freq()
h.generate_codes()

encoded_text = h.encode()
print(f"Encoded text: {encoded_text}")

decoded_text = h.decode(encoded_text)
print(f"Decoded text: {decoded_text}")
```
