import android.os.Bundle;
import android.view.View;
import android.widget.Button;
import android.widget.EditText;
import android.widget.RadioButton;
import android.widget.RadioGroup;
import android.widget.TextView;
import androidx.appcompat.app.AppCompatActivity;

public class MainActivity extends AppCompatActivity {

    private EditText principalEditText;
    private EditText interestEditText;
    private EditText termEditText;
    private RadioGroup loanTypeRadioGroup;
    private TextView resultTextView;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        principalEditText = findViewById(R.id.principal_edit_text);
        interestEditText = findViewById(R.id.interest_edit_text);
        termEditText = findViewById(R.id.term_edit_text);
        loanTypeRadioGroup = findViewById(R.id.loan_type_radio_group);
        resultTextView = findViewById(R.id.result_text_view);

        Button calculateButton = findViewById(R.id.calculate_button);
        calculateButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                double principal = Double.parseDouble(principalEditText.getText().toString());
                double annualInterestRate = Double.parseDouble(interestEditText.getText().toString());
                int termInYears = Integer.parseInt(termEditText.getText().toString());
                int loanType = loanTypeRadioGroup.getCheckedRadioButtonId();
                String result = calculateMonthlyPayment(principal, annualInterestRate, termInYears, loanType);
                resultTextView.setText(result);
            }
        });
    }

    private String calculateMonthlyPayment(double principal, double annualInterestRate, int termInYears, int loanType) {
        double monthlyInterestRate = annualInterestRate / 100 / 12;
        int numberOfPayments = termInYears * 12;

        // Calculate the monthly payment
        double monthlyPayment = principal * (monthlyInterestRate * Math.pow(1 + monthlyInterestRate, numberOfPayments)) /
                                (Math.pow(1 + monthlyInterestRate, numberOfPayments) - 1);

        return "Monthly Payment: $" + String.format("%.2f", monthlyPayment);
    }
}
```

