def caesar_cipher(text, shift):
    result = ""
    for char in text:
        if char.isalpha():
            shifted = ord(char) + shift
            if char.islower():
                result += chr((shifted - 97) % 26 + 97)
            elif char.isupper():
                result += chr((shifted - 65) % 26 + 65)
        else:
            result += char
    return result

